declare namespace SigApi {
    interface Factory2D {
        /**
         * Register a codeModule for a dashboard, window, etc.
         * @param {string} id A identifier, usually the dashboardName, windowName, etc.
         * @param {Function} createFunc A function returning an instance of a codeModule
         */
        register(id: string, createFunc: Function): void
        /**
         * Creates and returns codeModule instances
         * @param {string} id A identifier, usually the dashboardName, windowName, etc.
         * @returns {any[]} Newly created codeModule instances
         */
        requestInstances(id: string): any[]
    }
}
